// Generated by scripts/fetch-attorney-logos.mjs — do not edit by hand.
// Each logo was downloaded from that firm's own website (its declared icon)
// and bundled so it works offline. Icons smaller than 48px were
// skipped; those firms fall back to a monogram tile.
export const ATTORNEY_LOGOS = new Map<string, string>([
  ['baltattorneys.co.za', 'logos/attorneys/baltattorneys-co-za.png'],
  ['bezlaw.co.za', 'logos/attorneys/bezlaw-co-za.png'],
  ['c-law.co.za', 'logos/attorneys/c-law-co-za.png'],
  ['chimesvanwyk.co.za', 'logos/attorneys/chimesvanwyk-co-za.png'],
  ['dtllaw.co.za', 'logos/attorneys/dtllaw-co-za.png'],
  ['gerattorneys.co.za', 'logos/attorneys/gerattorneys-co-za.png'],
  ['haycocklaw.co.za', 'logos/attorneys/haycocklaw-co-za.png'],
  ['ilseschoeman.com', 'logos/attorneys/ilseschoeman-com.png'],
  ['lombardkotze.co.za', 'logos/attorneys/lombardkotze-co-za.png'],
  ['nicosmitinc.co.za', 'logos/attorneys/nicosmitinc-co-za.png'],
  ['nvzinc.co.za', 'logos/attorneys/nvzinc-co-za.png'],
  ['raubenheimers.co.za', 'logos/attorneys/raubenheimers-co-za.png'],
  ['rgprok.co.za', 'logos/attorneys/rgprok-co-za.png'],
  ['stenvertlaw.co.za', 'logos/attorneys/stenvertlaw-co-za.png'],
]);

export function getAttorneyLogo(website: string | undefined): string | undefined {
  if (!website) return undefined;
  try {
    return ATTORNEY_LOGOS.get(new URL(website).hostname.replace(/^www\./, ''));
  } catch {
    return undefined;
  }
}
